:root{--bg:#0c0d10;--fg:#e7e5df;--mute:#8b9098;--line:#23262d;--card:#131519;--soft:#191c22;--accent:#7dd3a8;--accent-ink:#0b1a12;--err:#e5484d;color-scheme:dark light;--sans:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Inter,sans-serif;--mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
@media (prefers-color-scheme:light){:root{--bg:#faf9f6;--fg:#1c1e22;--mute:#69707a;--line:#e6e2da;--card:#fff;--soft:#f1efe9;--accent:#2f8f63;--accent-ink:#f4fbf6}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.65 var(--sans)}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline;text-underline-offset:3px}
main{max-width:42rem;margin:0 auto;padding:4rem 1.25rem 5rem;animation:fade .4s ease-out}@keyframes fade{from{opacity:0;transform:translateY(5px)}}@media (prefers-reduced-motion:reduce){main{animation:none}.dot.open{animation:none}}
header.me{display:flex;gap:1.1rem;align-items:center;margin-bottom:2.5rem;position:relative}header.me img{width:56px;height:56px;border-radius:15px;flex:none;image-rendering:auto}header.me h1{font-size:1.75rem;line-height:1.2;margin:0 0 .25rem;letter-spacing:-.01em}header.me p{margin:0;color:var(--mute)}
section.c{margin-top:2.75rem;position:relative}
.label{display:flex;align-items:baseline;gap:.6rem;margin:0 0 1rem;padding-bottom:.45rem;border-bottom:1px solid var(--line);font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mute);font-weight:600}.label .grow{flex:1}
.ev{font-weight:400;letter-spacing:0;text-transform:none;font-size:.72rem;opacity:.5;color:var(--mute)}.ev:hover{opacity:1;text-decoration:none;color:var(--accent)}
.draft{font-size:.62rem;color:var(--accent);border:1px dashed var(--accent);border-radius:4px;padding:0 .3rem;letter-spacing:0;text-transform:none;font-weight:500;margin-left:.4rem}
.md p{margin:0 0 1rem}.md>:last-child{margin-bottom:0}.md h1,.md h2,.md h3{font-size:1.02rem;margin:1.4rem 0 .5rem}.md ul,.md ol{padding-left:1.3rem;margin:0 0 1rem}.md li{margin:.15rem 0}
.md code{font:.88em var(--mono);background:var(--soft);padding:.1em .35em;border-radius:4px}.md pre{background:var(--soft);padding:1rem;border-radius:8px;overflow:auto}.md pre code{background:none;padding:0}.md img{max-width:100%;border-radius:8px}
.md blockquote{margin:0 0 1rem;padding-left:1rem;border-left:2px solid var(--line);color:var(--mute)}.md hr{border:0;border-top:1px solid var(--line);margin:1.5rem 0}
.courses{display:grid;grid-template-columns:repeat(auto-fill,minmax(14.5rem,1fr));gap:.45rem;list-style:none;margin:.75rem 0 0;padding:0}
.courses li{font-size:.78rem;line-height:1.3;padding:.42rem .6rem;border-radius:8px;border:1px solid color-mix(in srgb,var(--accent) 24%,transparent);background:color-mix(in srgb,var(--accent) var(--g,8%),transparent);transition:transform .15s}.courses li:hover{transform:translateY(-1px)}
.courses li b{display:block;font:600 .66rem var(--mono);letter-spacing:.05em;color:var(--accent);margin-bottom:.12rem}.courses .y1{--g:6%}.courses .y2{--g:13%}.courses .y3{--g:21%}.courses .y4{--g:31%}
.courses .other{border-color:var(--line);background:var(--soft)}.courses .other b{color:var(--mute)}.legend{font-size:.72rem;color:var(--mute);margin:.6rem 0 0}
.items{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:1.25rem}.item{display:flex;gap:1rem;align-items:flex-start;position:relative}.item img.th{width:64px;height:64px;object-fit:cover;border-radius:8px;flex:none}
#writing .item img.th{width:92px;height:120px;object-fit:cover;object-position:top;border:1px solid var(--line);border-radius:4px;background:#fff;box-shadow:0 6px 18px rgba(0,0,0,.25);transition:transform .2s}#writing .item:hover img.th{transform:translateY(-2px) rotate(-.5deg)}
.item .b{min-width:0;flex:1}.item .t{font-weight:600;font-size:1.02rem}.item .t a{color:var(--fg)}.item .t a:hover{color:var(--accent)}.item .s{color:var(--mute);margin:.1rem 0 .35rem}.item .md{font-size:.92rem}.item .meta,.note .meta{display:flex;gap:.6rem;align-items:center;margin-top:.35rem;font-size:.72rem;color:var(--mute)}
.note{padding:.9rem 0;border-top:1px solid var(--line)}.note:first-of-type{border-top:0;padding-top:0}.note time{display:block;font-size:.74rem;color:var(--mute);margin-bottom:.2rem}
footer{margin-top:3.5rem;padding-top:1.25rem;border-top:1px solid var(--line);font-size:.85rem;color:var(--mute)}footer .links{display:flex;flex-wrap:wrap;gap:.3rem 1.1rem;margin-bottom:.7rem}
.status{display:flex;flex-wrap:wrap;gap:.4rem 1rem;align-items:center;font-size:.76rem}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--line);margin-right:.35rem;vertical-align:1px}
.dot.open{background:var(--accent);animation:pulse 2.6s ease-out infinite}@keyframes pulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--accent) 55%,transparent)}70%{box-shadow:0 0 0 6px transparent}100%{box-shadow:0 0 0 0 transparent}}.dot.err{background:var(--err)}
button{font:inherit;font-size:.85rem;color:var(--fg);background:var(--soft);border:1px solid var(--line);border-radius:8px;padding:.45rem .8rem;cursor:pointer;line-height:1.2}button:hover{border-color:var(--mute)}
button.pri{background:var(--accent);color:var(--accent-ink);border-color:transparent;font-weight:600}button.sm{font-size:.72rem;padding:.22rem .5rem}button.lnk{background:none;border:0;padding:0;color:var(--accent);font-size:inherit}button.lnk:hover{text-decoration:underline}button.danger{color:var(--err)}button:disabled{opacity:.5;cursor:default}
input,textarea{font:inherit;color:var(--fg);background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;width:100%}textarea{min-height:5rem;resize:vertical;font-size:.92rem}input:focus,textarea:focus{outline:none;border-color:var(--accent)}
.row{display:flex;gap:.5rem;margin-top:1rem;flex-wrap:wrap;align-items:center}.empty{color:var(--mute);font-size:.9rem;margin:0}
.chat{border:1px solid var(--line);border-radius:12px;background:var(--card);overflow:hidden}.chat .who{display:flex;gap:.6rem;align-items:center;flex-wrap:wrap;padding:.6rem .8rem;border-bottom:1px solid var(--line);font-size:.82rem;color:var(--mute)}.chat .who input{max-width:12rem;padding:.3rem .5rem;font-size:.85rem}
.chat .log{max-height:24rem;overflow:auto;padding:1rem;display:flex;flex-direction:column;gap:.45rem}.chat .hint{font-size:.82rem;color:var(--mute);padding:1rem;border-bottom:1px solid var(--line)}
.msg{max-width:84%;padding:.5rem .8rem;border-radius:12px;background:var(--soft);font-size:.92rem;white-space:pre-wrap;word-break:break-word;align-self:flex-start;border-bottom-left-radius:3px}.msg.out{align-self:flex-end;background:var(--accent);color:var(--accent-ink);border-bottom-left-radius:12px;border-bottom-right-radius:3px}.msg small{display:block;font-size:.66rem;opacity:.65;margin-top:.15rem}
.chat form{display:flex;gap:.5rem;padding:.7rem .8rem;border-top:1px solid var(--line)}.chat form textarea{min-height:2.6rem;max-height:10rem}.threads{display:flex;gap:.4rem;flex-wrap:wrap;padding:.6rem .8rem;border-bottom:1px solid var(--line)}.threads button.on{border-color:var(--accent)}
.badge{display:inline-block;min-width:1.2em;padding:0 .35em;border-radius:999px;background:var(--accent);color:var(--accent-ink);font-size:.66rem;font-weight:700;margin-left:.35rem;vertical-align:1px}.keys{padding:.5rem .8rem;border-top:1px solid var(--line);font-size:.76rem;color:var(--mute)}.keys summary{cursor:pointer}.keys .row{margin-top:.4rem}
.toasts{position:fixed;right:1rem;bottom:1rem;display:flex;flex-direction:column;gap:.4rem;z-index:40}.toast{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:.5rem .8rem;font-size:.78rem;max-width:22rem;box-shadow:0 8px 30px rgba(0,0,0,.3)}.toast.err{border-color:var(--err)}
.spin{display:inline-block;width:.8em;height:.8em;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite;vertical-align:-1px;margin-right:.35rem}@keyframes spin{to{transform:rotate(360deg)}}
@media (max-width:600px){main{padding:2.5rem 1rem 4rem}header.me{gap:.9rem}.item img.th{width:48px;height:48px}#writing .item img.th{width:72px;height:94px}}
#writing a[data-preview]{flex:none;line-height:0}.preview{flex-basis:100%;width:100%;height:34rem;border:1px solid var(--line);border-radius:8px;margin-top:.75rem;background:#fff}.item{flex-wrap:wrap}
